<template><div class="page"><div class="container"><div class="eyebrow">SEARCH</div><h1 class="h1">Find a product.</h1><input v-model="q" class="input search" placeholder="Search electrical products…"/><div class="product-grid" v-if="results.length"><ProductCard v-for="p in results" :key="p.id" :product="p" @add="cart.add(p)"/></div><div v-else class="empty">No products match “{{q}}”.</div></div></div></template><script setup lang="ts">import {computed,ref} from 'vue';import ProductCard from '../components/commerce/ProductCard.vue';import {products} from '../services/mock';import {useCartStore} from '../stores/cart';const q=ref('');const cart=useCartStore();const results=computed(()=>products.filter(p=>`${p.name} ${p.category} ${p.brand}`.toLowerCase().includes(q.value.toLowerCase())))</script><style scoped>.search{max-width:650px;margin:5px 0 45px}.product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}@media(max-width:900px){.product-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.product-grid{grid-template-columns:1fr 1fr}}</style>
